#!/usr/bin/env node
// Condense a captured conversation JSONL into a readable digest.
// usage: node condense-log.mjs <file> [mode]
//   mode: human (default) | flow | tools
import { createInterface } from 'node:readline';
import { createReadStream } from 'node:fs';

const [, , file, mode = 'human'] = process.argv;
const rl = createInterface({ input: createReadStream(file), crlfDelay: Infinity });

const clip = (s, n) => (s.length > n ? s.slice(0, n) + ` …[+${s.length - n}]` : s);
const isHookish = (t) =>
  t.startsWith('<') ||
  t.startsWith('[Request interrupted') ||
  t.startsWith('Caveat:') ||
  t.startsWith('Claudinite self-test');

let i = 0;
for await (const line of rl) {
  i++;
  if (!line.trim()) continue;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = (e.timestamp || '').slice(11, 19);
  const msg = e.message;
  if (e.type === 'user' && msg) {
    const parts = Array.isArray(msg.content) ? msg.content : [{ type: 'text', text: msg.content }];
    for (const p of parts) {
      if (p.type === 'text' && typeof p.text === 'string') {
        const t = p.text.trim();
        if (!t || isHookish(t)) continue;
        console.log(`\n[${i} ${ts}] USER: ${clip(t, 2500)}`);
      } else if (mode !== 'human' && p.type === 'tool_result') {
        const c = typeof p.content === 'string' ? p.content : JSON.stringify(p.content);
        console.log(`[${i} ${ts}]   result${p.is_error ? '(ERR)' : ''}: ${clip((c || '').replace(/\s+/g, ' '), 300)}`);
      }
    }
  } else if (e.type === 'assistant' && msg && mode !== 'human') {
    for (const p of msg.content || []) {
      if (p.type === 'text' && p.text.trim()) {
        console.log(`[${i} ${ts}] ASSISTANT: ${clip(p.text.trim().replace(/\s+/g, ' '), mode === 'flow' ? 1200 : 200)}`);
      } else if (p.type === 'tool_use') {
        const a = JSON.stringify(p.input || {}).replace(/\s+/g, ' ');
        console.log(`[${i} ${ts}]   TOOL ${p.name}: ${clip(a, mode === 'tools' ? 600 : 220)}`);
      }
    }
  }
}

