    // The branch's own commits since the merge-base, oldest first, each with its
    // changed files and committer date — for rules about the ORDER work landed in
    // (ctx.commits keeps only messages). Merges excluded: their file list is
    // empty under --name-only and their content arrives via their parents.
    commitsWithFiles() {
      if (!mergeBase()) return [];
      const out = gitTry(root, 'log', '--reverse', '--no-merges', '--name-only',
        '--format=%x00%H%x1f%cI%x1f%s', `${mergeBase()}..HEAD`);
      const parsed = [];
      for (const block of (out || '').split('\0')) {
        if (!block.trim()) continue;
        const [head, ...rest] = block.trim().split('\n');
        const [sha, date, subject] = head.split('\x1f');
        parsed.push({ sha, date, subject, files: rest.map((f) => f.trim()).filter(Boolean) });
      }
      return parsed;
    },

    // Merge commits the current change introduces — those on HEAD's first-parent
    // chain since the merge-base with the base branch (the squash-only effect
    // check, scoped to the work). Empty when no base resolves or the branch is
    // even with it; pre-existing merges already on the base are out of range.
    //
    // The range alone trusts the merge-base to be right, and it isn't always: a
    // shallow clone's grafted boundary or a criss-cross history can hand back a
    // merge-base that sweeps the base branch's own merges into the range. So each
    // candidate is confirmed against the base ref itself — a merge already on the
    // base branch was never introduced here, whatever the range says. Offline and
    // exact, and it holds when refreshBaseRef couldn't run.
    introducedMergeCommits() {
      if (!mergeBase()) return [];
      const out = gitTry(root, 'log', '--merges', '--first-parent', '--format=%h %s', `${mergeBase()}..HEAD`);
      return lines(out).map((l) => {
        const i = l.indexOf(' ');
        return { sha: l.slice(0, i), subject: l.slice(i + 1) };
      }).filter(({ sha }) => !onBaseBranch(sha));
    },

    // Fixed-string search across tracked files; git grep exits 1 on no match.
    // The vendored shared mount is structurally out of the sweep (canon-owned,
=== read-live 100-135 ===
// together is what makes a structural exemption visible as one.
export const acceptanceReasons = (config, ruleId) => (Array.isArray(config?.accept) ? config.accept : [])
  .filter((a) => a?.rule === ruleId)
  .map((a) => ({ file: a.file ?? a.path ?? null, reason: a.reason ?? a.why ?? null }));

// When this repo first declared a pack - the adoption window's start. Read from the
// settings file's own history, deepened as far as the checkout reaches. A shallow
// clone that does not reach it answers null, and the `adoption` rules then read
// *not recorded* rather than judging against a date that is really the clone's.
export function packDeclaredAt(root, packId) {
  const run = (args) => execFileSync('git', args,
    { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
  try {
    const first = run(['log', '--reverse', '--format=%H %aI',
      '-S', `"${packId}"`, '--', '.claudinite-settings.json']).trim().split('\n')[0];
    if (!first) return null;
    const [sha, at] = first.split(' ');
    // The earliest commit that MENTIONS the pack is the one that declared it only
    // if the commit before it did not already carry it. Without that second read
    // the search answers with the earliest commit the checkout happens to reach,
    // which on a shallow clone is the clone's own horizon - and the adoption
    // window then becomes a property of how deeply this checkout was fetched, so
    // one review over one record finds different things on two checkouts.
    let parent = null;
    try { parent = run(['rev-parse', '--verify', '-q', `${sha}^`]).trim(); } catch { parent = null; }
    if (!parent) {
      // No parent here: either the repository's own first commit, which is a real
      // answer, or a shallow boundary, where the declaration predates everything
      // we can see and its date is simply not knowable.
      return run(['rev-parse', '--is-shallow-repository']).trim() === 'true' ? null : at;
    }
    let before = '';
    try { before = run(['show', `${parent}:.claudinite-settings.json`]); } catch { before = ''; }
    return before.includes(`"${packId}"`) ? null : at;
  } catch { return null; }
}

