import('node:child_process').then(async ({execFileSync})=>{
const fs=await import('node:fs');
const files=execFileSync('git',['ls-files','*.mjs'],{encoding:'utf8'}).split('\n').filter(Boolean).filter(f=>!f.startsWith('.claudinite/shared'));
const {stripComments}=await import('/home/user/Claudinite/engine/checks/helpers/code-scanning.mjs');
const M=/(^|[^\w-])(--reverse|-S)(\b|[\`'\"])/;
for(const f of files){
  const txt=stripComments(fs.readFileSync(f,'utf8'));
  if(/--is-shallow-repository|--unshallow/.test(txt)) continue;
  const lines=txt.split('\n');
  lines.forEach((l,i)=>{
    if(!M.test(l)) return;
    const blk=(lines[i+1]||'');
    if(/\.\./.test(l)||/\.\./.test(blk)) return;
    console.log(f+':'+(i+1)+': '+l.trim().slice(0,110));
  });
}
});"

