import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { stripComments } from '/home/user/Claudinite/engine/checks/helpers/code-scanning.mjs';

const all = execFileSync('git', ['ls-files', '*.mjs'], { cwd: '/home/user/Claudinite', encoding: 'utf8' })
  .split('\n').filter(Boolean);
const files = all.filter((f) => f.indexOf('.claudinite/shared') !== 0);
const M = /(^|[^\w-])(--reverse|-S)(\b|[`'"])/;
let n = 0;
for (const f of files) {
  const txt = stripComments(readFileSync('/home/user/Claudinite/' + f, 'utf8'));
  if (/--is-shallow-repository|--unshallow/.test(txt)) continue;
  const lines = txt.split('\n');
