    if (!M.test(l)) return;
    const blk = lines[i + 1] || '';
    if (/\.\./.test(l) || /\.\./.test(blk)) return;
    n++;
    console.log(f + ':' + (i + 1) + ': ' + l.trim().slice(0, 110));
  });
}
console.log('TOTAL', n);

